import { useState } from 'react';
import './ChipBar.css';

interface ChipBarProps {
  labels: string[];
}

// ChipBar owns only visual pressed state. Connecting pressed chips to grid
// filtering is handled externally — a parent will wire onFilterChange when ready.
export function ChipBar({ labels }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<Set<string>>(new Set());

  function toggle(label: string): void {
    setPressed((prev) => {
      const next = new Set(prev);
      if (next.has(label)) {
        next.delete(label);
      } else {
        next.add(label);
      }
      return next;
    });
  }

  return (
    <div className="chip-bar" role="group" aria-label="Filter chips">
      {labels.map((label) => (
        <button
          key={label}
          type="button"
          className="chip-bar__chip"
          aria-pressed={pressed.has(label)}
          onClick={() => toggle(label)}
        >
          {label}
        </button>
      ))}
    </div>
  );
}
